const KEY='northstar-erp-trial-v1';
const seed={products:[{id:'PRD-001',name:'Arabica Coffee Beans',category:'Raw materials',onHand:245,reorder:100,cost:180,price:280,uom:'kg'},{id:'PRD-002',name:'Cocoa Powder 1kg',category:'Finished goods',onHand:84,reorder:40,cost:95,price:155,uom:'bag'},{id:'PRD-003',name:'Paper Cups 12oz',category:'Packaging',onHand:18,reorder:50,cost:2.8,price:5,uom:'pcs'},{id:'PRD-004',name:'Dried Mango 500g',category:'Finished goods',onHand:132,reorder:40,cost:62,price:110,uom:'pack'},{id:'PRD-005',name:'Green Tea Leaves',category:'Raw materials',onHand:76,reorder:30,cost:120,price:195,uom:'kg'}],customers:['Siam Café Group','Bangkok Pantry Co.','Riverstone Hotels'],vendors:['Northern Harvest Ltd.','PackRight Cambodia','Mae Hong Son Cooperative'],sales:[{id:'SO-1048',customer:'Siam Café Group',product:'PRD-001',qty:24,unitPrice:280,status:'Invoiced',date:'2026-10-28'},{id:'SO-1047',customer:'Bangkok Pantry Co.',product:'PRD-004',qty:16,unitPrice:110,status:'Open',date:'2026-10-29'},{id:'SO-1046',customer:'Riverstone Hotels',product:'PRD-002',qty:12,unitPrice:155,status:'Invoiced',date:'2026-10-27'}],purchases:[{id:'PO-2031',vendor:'Northern Harvest Ltd.',product:'PRD-001',qty:100,unitCost:180,status:'Open',date:'2026-10-29'},{id:'PO-2030',vendor:'PackRight Cambodia',product:'PRD-003',qty:500,unitCost:2.8,status:'Received',date:'2026-10-26'}],ledger:[{id:'JE-3108',date:'2026-10-28',reference:'SO-1048',account:'Sales revenue',debit:0,credit:6720,memo:'Product sale'},{id:'JE-3107',date:'2026-10-28',reference:'SO-1048',account:'Accounts receivable',debit:6720,credit:0,memo:'Customer invoice'},{id:'JE-3106',date:'2026-10-26',reference:'PO-2030',account:'Inventory',debit:1400,credit:0,memo:'Goods received'},{id:'JE-3105',date:'2026-10-26',reference:'PO-2030',account:'Accounts payable',debit:0,credit:1400,memo:'Supplier liability'}],adjustments:[]};
const budgetMonth=new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0');
const BUDGET_SEED=[{id:'BUD-1',period:budgetMonth,assignmentCategory:'INVENTORY',assignmentRef:'WH-BKK',glAccount:'1100',amount:250000,status:'Approved'},{id:'BUD-2',period:budgetMonth,assignmentCategory:'COST_CENTER',assignmentRef:'CC-PROC',glAccount:'5000',amount:250000,status:'Approved'},{id:'BUD-3',period:budgetMonth,assignmentCategory:'ASSET',assignmentRef:'AST-NEW',glAccount:'1500',amount:250000,status:'Approved'},{id:'BUD-4',period:budgetMonth,assignmentCategory:'PROJECT',assignmentRef:'PRJ-GEN',glAccount:'6000',amount:250000,status:'Approved'}];
let db;try{db=JSON.parse(localStorage.getItem(KEY))||structuredClone(seed)}catch{db=structuredClone(seed)}
db.kpis=Array.isArray(db.kpis)?db.kpis:[];
db.budgets=Array.isArray(db.budgets)?db.budgets:structuredClone(BUDGET_SEED);
db.purchases.forEach(p=>{p.assignmentCategory=p.assignmentCategory||'INVENTORY';p.assignmentRef=p.assignmentRef||'WH-BKK';p.glAccount=p.glAccount||'1100'});
db.products.forEach(p=>{p.parentId=p.parentId||null;p.assignmentCategory=p.assignmentCategory||'INVENTORY';p.assignmentRef=p.assignmentRef||'WH-BKK';p.glAccount=p.glAccount||'1100';p.materialClass=p.assignmentCategory});const pages=[['overview','⌂','Overview'],['sales','↗','Sales'],['purchasing','↙','Purchasing'],['planning','☷','Material planning'],['products','⬡','Product hierarchy'],['supplychain','◉','Supply chain KPIs'],['inventory','▦','Inventory'],['finance','◈','Finance'],['masters','◇','Master data'],['roadmap','☷','Setup & plan']];let current=pages.some(p=>p[0]===location.hash.slice(1))?location.hash.slice(1):'overview';
const KPI_DEFS=[
 {id:'po-fulfillment',name:'Purchase order fulfillment',unit:'%',direction:'up',formula:'Purchase orders completed on time ÷ purchase orders due × 100',icon:'↙'},
 {id:'cost-control',name:'Procurement & logistics cost control',unit:'%',direction:'down',formula:'Actual procurement and logistics spend ÷ approved budget × 100',icon:'$'},
 {id:'supplier-reliability',name:'Supplier performance & reliability',unit:'%',direction:'up',formula:'Complete, accepted supplier deliveries ÷ total deliveries × 100',icon:'♧'},
 {id:'schedule-compliance',name:'Shipment & delivery schedule compliance',unit:'%',direction:'up',formula:'Shipments delivered by promised date ÷ shipments due × 100',icon:'◷'},
 {id:'inventory-accuracy',name:'Inventory availability & stock accuracy',unit:'%',direction:'up',formula:'Available, accurate stock checks ÷ all stock checks × 100',icon:'▦'},
 {id:'team-cycle-time',name:'Purchasing & logistics team performance',unit:'days',direction:'down',formula:'Average working days from purchase request to purchase order',icon:'♙'},
 {id:'issue-resolution',name:'Timely reporting & issue resolution',unit:'%',direction:'up',formula:'Operational issues resolved within SLA ÷ issues closed × 100',icon:'✓'}
];
const ASSIGNMENT_TYPES=[
 {id:'INVENTORY',label:'Inventory / stock',reference:'WH-BKK',glAccount:'1100',glName:'Inventory Asset'},
 {id:'COST_CENTER',label:'Cost center',reference:'CC-PROC',glAccount:'5000',glName:'Purchasing Expense'},
 {id:'ASSET',label:'Fixed asset',reference:'AST-NEW',glAccount:'1500',glName:'Fixed Assets'},
 {id:'PROJECT',label:'Project / WBS',reference:'PRJ-GEN',glAccount:'6000',glName:'Project Expense'}
];
const $=s=>document.querySelector(s),money=n=>'$'+Number(n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){localStorage.setItem(KEY,JSON.stringify(db))}function dateNow(){return new Date().toISOString().slice(0,10)}function product(id){return db.products.find(p=>p.id===id)}function newId(prefix,rows,start){return prefix+'-'+(Math.max(start,...rows.map(x=>Number((x.id.match(/\d+/)||[])[0])||0))+1)}function status(s){return '<span class="status '+s.toLowerCase().replace(' ','-')+'">'+s+'</span>'}function nav(){$('#nav').innerHTML=pages.map(([id,icon,name])=>'<button class="nav-item '+(id===current?'active':'')+'" data-page="'+id+'"><span class="nav-icon">'+icon+'</span><span class="nav-label">'+name+'</span></button>').join('');$('#nav').querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page))}function go(id){current=id;history.replaceState(null,'','#'+id);nav();render()}
function heading(title,sub,action=''){return '<div class="welcome-row"><div><div class="eyebrow">ABC Co Ltd · Cambodia</div><h1 class="page-title">'+title+'</h1><div class="subtitle">'+sub+'</div></div>'+action+'</div>'}function metric(label,value,sub,icon){return '<div class="metric"><div class="metric-top">'+label+'<span class="metric-icon">'+icon+'</span></div><div class="metric-value">'+value+'</div><div class="metric-bottom">'+sub+'</div></div>'}function invValue(){return db.products.reduce((a,p)=>a+p.onHand*p.cost,0)}function render(){const d=new Date;$('#today').textContent=d.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'});$('#crumb').textContent=pages.find(x=>x[0]===current)[2];const v={overview,sales:salesPage,purchasing:purchasePage,supplychain:supplyChainPage,planning:materialPlanningPage,products:productHierarchyPage,inventory:inventoryPage,finance:financePage,connected:connectedPage,masters:mastersPage,roadmap:roadmapPage};$('#page').innerHTML=v[current]();wireSearch()}
function overview(){const low=db.products.filter(p=>p.onHand<=p.reorder).length,orders=db.sales.filter(x=>x.status==='Open').length;return heading('Good morning, Lyly 👋','Here is your business snapshot for today.','<div class="actions"><button class="btn" onclick="go(\'roadmap\')">Implementation plan</button><button class="btn btn-primary" onclick="openModal(\'sales\')">＋ New sales order</button></div>')+'<div class="metrics">'+metric('Inventory value',money(invValue()),db.products.length+' stock items','▦')+metric('Open sales orders',orders,'Awaiting fulfillment','◷')+metric('Items to reorder',low,'Review stock levels','⚑')+metric('Posted journal entries',db.ledger.length,'Operational postings','◈')+'</div><div class="dashboard-grid"><div class="panel"><div class="panel-head"><div><div class="panel-title">Business activity</div><div class="panel-subtitle">Sales and purchases · last 7 days</div></div><span class="status received">Live trial data</span></div><div class="chart-wrap"><svg class="chart-svg" viewBox="0 0 600 200" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#51b987" stop-opacity=".2"/><stop offset="1" stop-color="#51b987" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M40 28H590M40 67H590M40 106H590M40 145H590M40 184H590"/><text x="0" y="31" class="chart-label">20k</text><text x="0" y="70" class="chart-label">15k</text><text x="0" y="109" class="chart-label">10k</text><text x="9" y="148" class="chart-label">5k</text><text x="20" y="187" class="chart-label">0</text><path class="chart-area" d="M40 140 C75 128 90 145 125 112 S180 118 205 93 S255 109 285 78 S340 92 365 57 S420 86 445 68 S505 87 535 46 S570 62 590 35 L590 184 L40 184Z"/><path class="chart-line" d="M40 140 C75 128 90 145 125 112 S180 118 205 93 S255 109 285 78 S340 92 365 57 S420 86 445 68 S505 87 535 46 S570 62 590 35"/><text x="40" y="199" class="chart-label">24 Oct</text><text x="150" y="199" class="chart-label">26 Oct</text><text x="260" y="199" class="chart-label">27 Oct</text><text x="380" y="199" class="chart-label">28 Oct</text><text x="490" y="199" class="chart-label">29 Oct</text><text x="550" y="199" class="chart-label">30 Oct</text></svg></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Work queue</div><div class="panel-subtitle">Actions that need attention</div></div></div><div class="process-list"><div class="process"><div class="process-icon">↗</div><div><b>Sales orders to fulfill</b><small>Review, reserve, and ship</small></div><div class="process-count">'+orders+'</div></div><div class="process"><div class="process-icon">↙</div><div><b>Purchase orders to receive</b><small>Post goods into inventory</small></div><div class="process-count">'+db.purchases.filter(isInboundPurchase).length+'</div></div><div class="process"><div class="process-icon">⚑</div><div><b>Items below reorder point</b><small>Review replenishment needs</small></div><div class="process-count">'+low+'</div></div></div></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Recent sales orders</div><div class="panel-subtitle">Customer order-to-cash activity</div></div><button class="text-link" onclick="go(\'sales\')">View all →</button></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Product</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody>'+db.sales.slice(0,5).map(s=>'<tr><td class="td-strong">'+s.id+'</td><td>'+esc(s.customer)+'</td><td>'+esc(product(s.product).name)+'</td><td>'+s.date+'</td><td>'+money(s.qty*s.unitPrice)+'</td><td>'+status(s.status)+'</td></tr>').join('')+'</tbody></table></div></div>'}
function tablePage(title,sub,btn,cols,rows){return heading(title,sub,btn)+'<div class="page-tools"><input class="search" id="tableSearch" placeholder="⌕  Search '+title.toLowerCase()+'..."><span class="muted" style="font-size:10px">'+rows.length+' records</span></div><div class="panel table-panel"><div class="table-wrap"><table><thead><tr>'+cols.map(c=>'<th>'+c+'</th>').join('')+'</tr></thead><tbody>'+ (rows.join('')||'<tr><td class="empty" colspan="'+cols.length+'">No records yet. Create a transaction to get started.</td></tr>')+'</tbody></table></div></div>'}
function salesPage(){return tablePage('Sales orders','Order to cash · Create, fulfill, and invoice customer orders','<button class="btn btn-primary" onclick="openModal(\'sales\')">＋ New sales order</button>',['Order','Customer','Product','Qty','Amount','Date','Status','Action'],db.sales.map(s=>'<tr><td class="td-strong">'+s.id+'</td><td>'+esc(s.customer)+'</td><td>'+esc(product(s.product).name)+'</td><td>'+s.qty+'</td><td>'+money(s.qty*s.unitPrice)+'</td><td>'+s.date+'</td><td>'+status(s.status)+'</td><td>'+(s.status==='Open'?'<button class="btn btn-sm btn-primary" onclick="shipSale(\''+s.id+'\')">Ship & invoice</button>':'')+'</td></tr>'))}
function currentPeriod(){const d=new Date;return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}function assignmentType(id){return ASSIGNMENT_TYPES.find(x=>x.id===id)||ASSIGNMENT_TYPES[0]}
function isCommittedPurchase(p){return ['Open','Issued','Received'].includes(p.status)}function isInboundPurchase(p){return ['Open','Issued'].includes(p.status)}
function budgetUsage(b){return db.purchases.filter(p=>isCommittedPurchase(p)&&(p.budgetPeriod||p.date?.slice(0,7))===b.period&&p.assignmentCategory===b.assignmentCategory&&p.assignmentRef===b.assignmentRef&&String(p.glAccount)===String(b.glAccount)).reduce((n,p)=>n+Number(p.qty)*Number(p.unitCost),0)}
function budgetPanel(){const month=currentPeriod(),budgets=db.budgets.filter(b=>b.period===month);return '<div class="panel budget-panel"><div class="panel-head"><div><div class="panel-title">Approved budgets · '+month+'</div><div class="panel-subtitle">Demo limits: replace with approved amounts. Issuing a PO reserves its commitment.</div></div><button class="btn btn-sm" onclick="openBudgetModal()">＋ Add budget</button></div><div class="table-wrap"><table><thead><tr><th>Assignment</th><th>Reference</th><th>GL account</th><th>Budget</th><th>Committed</th><th>Available</th><th>Status</th><th></th></tr></thead><tbody>'+(budgets.map(b=>'<tr><td>'+esc(assignmentType(b.assignmentCategory).label)+'</td><td>'+esc(b.assignmentRef)+'</td><td>'+b.glAccount+' · '+esc(assignmentType(b.assignmentCategory).glName)+'</td><td>'+money(b.amount)+'</td><td>'+money(budgetUsage(b))+'</td><td class="'+(Number(b.amount)-budgetUsage(b)<0?'budget-over':'')+'">'+money(Number(b.amount)-budgetUsage(b))+'</td><td>'+status(b.status)+'</td><td><button class="text-link" onclick="openBudgetModal(\''+b.id+'\')">Edit</button></td></tr>').join('')||'<tr><td class="empty" colspan="8">No budgets for this month. Add and approve a budget before issuing purchase orders.</td></tr>')+'</tbody></table></div></div>'}
function openBudgetModal(id=''){const row=db.budgets.find(b=>b.id===id),type=assignmentType(row?.assignmentCategory||'INVENTORY'),choices=ASSIGNMENT_TYPES.map(x=>'<option value="'+x.id+'" '+(x.id===type.id?'selected':'')+'>'+x.label+'</option>').join('');$('#modal-root').innerHTML='<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><form class="modal" onsubmit="saveBudget(event,\''+(row?row.id:'')+'\')"><div class="modal-head"><div><h2>'+(row?'Edit budget':'Add budget')+'</h2><p>Set the approved amount for one account assignment and period.</p></div><button type="button" class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Budget period</label><input name="period" type="month" value="'+(row?row.period:currentPeriod())+'" required></div><div class="field"><label>Account assignment</label><select name="assignmentCategory" id="budgetCategory">'+choices+'</select></div><div class="field"><label>Assignment reference</label><input name="assignmentRef" id="budgetRef" value="'+esc(row?row.assignmentRef:type.reference)+'" required></div><div class="field"><label>GL account</label><input name="glAccount" id="budgetGL" value="'+type.glAccount+' · '+esc(type.glName)+'" readonly></div><div class="field"><label>Budget amount ($)</label><input name="amount" type="number" min="0.01" step="0.01" value="'+(row?row.amount:'')+'" required></div><div class="field"><label>Budget status</label><select name="status"><option value="Draft" '+(row?.status==='Draft'?'selected':'')+'>Draft</option><option value="Approved" '+(!row||row.status==='Approved'?'selected':'')+'>Approved</option></select></div><div class="form-note">The demo checks committed purchase orders against approved budgets by month, assignment reference, and GL account.</div></div></div><div class="modal-foot"><button class="btn" type="button" onclick="closeModal()">Cancel</button><button class="btn btn-primary" type="submit">Save budget</button></div></form></div>';$('#budgetCategory').onchange=()=>{const x=assignmentType($('#budgetCategory').value);$('#budgetRef').value=x.reference;$('#budgetGL').value=x.glAccount+' · '+x.glName}}
function saveBudget(e,id){e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),a=assignmentType(f.assignmentCategory),amount=Number(f.amount);if(!f.period||!f.assignmentRef.trim()||!Number.isFinite(amount)||amount<=0){toast('Enter a period, assignment, and positive budget amount.');return}if(db.budgets.some(b=>b.id!==id&&b.period===f.period&&b.assignmentCategory===a.id&&b.assignmentRef===f.assignmentRef.trim()&&String(b.glAccount)===a.glAccount)){toast('A budget already exists for this assignment and period. Edit it instead.');return}const budget={id:id||'BUD-'+Date.now(),period:f.period,assignmentCategory:a.id,assignmentRef:f.assignmentRef.trim(),glAccount:a.glAccount,amount,status:f.status};if(id)db.budgets[db.budgets.findIndex(b=>b.id===id)]=budget;else db.budgets.unshift(budget);save();closeModal();render();toast('Budget saved.')}
function issuePO(id){const po=db.purchases.find(p=>p.id===id);if(!po||po.status!=='Draft')return;const type=assignmentType(po.assignmentCategory),period=currentPeriod(),budget=db.budgets.find(b=>b.period===period&&b.status==='Approved'&&b.assignmentCategory===type.id&&b.assignmentRef===po.assignmentRef&&String(b.glAccount)===type.glAccount);if(!budget){toast('No approved '+type.label+' budget for '+po.assignmentRef+' in '+period+'. Add an approved budget first.');return}const committed=db.purchases.filter(p=>p.id!==po.id&&isCommittedPurchase(p)&&(p.budgetPeriod||p.date?.slice(0,7))===period&&p.assignmentCategory===type.id&&p.assignmentRef===po.assignmentRef&&String(p.glAccount)===type.glAccount).reduce((n,p)=>n+Number(p.qty)*Number(p.unitCost),0),amount=Number(po.qty)*Number(po.unitCost),available=Number(budget.amount)-committed;if(amount>available+0.005){toast('Budget exceeded. '+money(available)+' available; PO requires '+money(amount)+'.');return}po.status='Issued';po.budgetPeriod=period;po.issuedDate=dateNow();save();render();toast(id+' issued within approved budget.')}function purchasePage(){const cols=['Order','Supplier','PO line','Qty','Amount','Account assignment','Reference','GL account','Expected arrival','Logistics','Status','Action'],rows=db.purchases.map(p=>{const a=assignmentType(p.assignmentCategory),actions=p.status==='Draft'?'<button class="btn btn-sm btn-primary" onclick="issuePO(\''+p.id+'\')">Issue PO</button>':isInboundPurchase(p)?'<button class="btn btn-sm" onclick="openLogisticsModal(\''+p.id+'\')">Delivery</button> <button class="btn btn-sm btn-primary" onclick="receivePO(\''+p.id+'\')">Receive</button>':'';return '<tr><td class="td-strong">'+p.id+'</td><td>'+esc(p.vendor)+'</td><td>'+esc(product(p.product)?.name||p.product)+'</td><td>'+p.qty+' '+esc(product(p.product)?.uom||'')+'</td><td>'+money(p.qty*p.unitCost)+'</td><td>'+esc(a.label)+'</td><td>'+esc(p.assignmentRef||'—')+'</td><td>'+esc(p.glAccount)+' · '+esc(a.glName)+'</td><td>'+(p.expectedDate||'Not set')+'</td><td>'+status(logisticsState(p))+'</td><td>'+status(p.status)+'</td><td>'+actions+'</td></tr>'});return heading('Purchase orders','Create classified PO lines, manage approved budgets, and track inbound delivery','<button class="btn btn-primary" onclick="openModal(\'purchase\')">＋ New purchase order</button>')+budgetPanel()+'<div class="page-tools"><input class="search" id="tableSearch" placeholder="⌕  Search purchase orders..."><span class="muted" style="font-size:10px">'+rows.length+' records</span></div><div class="panel table-panel"><div class="table-wrap"><table class="purchase-table"><thead><tr>'+cols.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+(rows.join('')||'<tr><td class="empty" colspan="12">No purchase orders yet.</td></tr>')+'</tbody></table></div></div>'}function defaultEta(){const d=new Date;d.setDate(d.getDate()+14);return d.toISOString().slice(0,10)}
function materialPlan(p){const demand=db.sales.filter(x=>x.product===p.id&&x.status==='Open').reduce((n,x)=>n+Number(x.qty),0),inboundOrders=db.purchases.filter(x=>x.product===p.id&&isInboundPurchase(x)),inbound=inboundOrders.reduce((n,x)=>n+Number(x.qty),0),projected=Number(p.onHand)+inbound-demand,required=Math.max(0,Number(p.reorder)-projected),etas=inboundOrders.map(x=>x.expectedDate).filter(Boolean).sort();return {demand,inbound,inboundOrders,projected,required,eta:etas[0]||''}}
function logisticsState(po){if(po.status==='Draft')return 'Not issued';if(po.status==='Received')return 'Received';if(po.expectedDate&&po.expectedDate<dateNow())return 'Overdue';if(po.trackingRef||po.carrier)return 'In transit';return po.expectedDate?'Scheduled':'ETA missing'}
function productHierarchyPage(){
 const children=id=>db.products.filter(p=>(p.parentId||null)===id);
 const tree=(parent=null,level=1)=>children(parent).map(p=>{const a=assignmentType(p.assignmentCategory);return '<div class="product-node" style="--level:'+Math.min(level,6)+'"><div class="product-node-main"><span class="product-level">L'+level+'</span><div class="product-node-info"><b>'+esc(p.name)+'</b><small>'+esc(p.id)+' · '+esc(p.category||'Uncategorized')+' · '+esc(p.uom)+'</small></div><span class="product-class">'+esc(a.label)+'</span><span class="product-node-stock">'+Number(p.onHand||0)+' on hand</span><button class="btn btn-sm" onclick="openProductClassModal(\''+p.id+'\')">Edit PO class</button><button class="btn btn-sm" onclick="openProductModal(\''+p.id+'\')">＋ Add child</button></div><div class="product-node-meta">Default PO class: '+esc(a.label)+' · '+esc(p.assignmentRef)+' · GL '+esc(p.glAccount)+' · '+(p.reorder||0)+' reorder point</div>'+(children(p.id).length?'<div class="product-children">'+tree(p.id,level+1)+'</div>':'')+'</div>'}).join('');
 const roots=tree(null,1);return heading('Product hierarchy','Organize materials at any depth. Products can be roots, children, or leaves; each material carries its default PO class.','<button class="btn btn-primary" onclick="openProductModal()">＋ New product / material</button>')+'<div class="notice"><b>Material planning:</b> Each product may sit at any hierarchy level. Use Add child to build deeper levels; products with no parent remain at the root. Purchase orders inherit the selected material’s default class, reference, and GL account.</div><div class="product-tree">'+(roots||'<div class="empty">No products yet. Create a root product to begin.</div>')+'</div>';
}
function openProductModal(parentId=''){const parent=parentId?product(parentId):null,choices=ASSIGNMENT_TYPES.map(a=>'<option value="'+a.id+'" '+(a.id===(parent?.assignmentCategory||'INVENTORY')?'selected':'')+'>'+esc(a.label)+'</option>').join('');$('#modal-root').innerHTML='<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><form class="modal" onsubmit="saveProduct(event)"><div class="modal-head"><div><h2>'+(parent?'Add child product':'Create product / material')+'</h2><p>'+(parent?'Under '+esc(parent.name)+' · this can become level '+(productLevel(parent.id)+1):'Create a root item or select a parent to add it under another product.')+'</p></div><button type="button" class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid"><div class="field full"><label>Product name</label><input name="name" required maxlength="150" placeholder="e.g. 250 ml bottle"></div><div class="field"><label>Parent product (optional)</label><select name="parentId"><option value="">No parent · root product</option>'+db.products.map(p=>'<option value="'+p.id+'" '+(p.id===parentId?'selected':'')+'>'+esc(p.name)+' · Level '+productLevel(p.id)+'</option>').join('')+'</select></div><div class="field"><label>Product group</label><input name="category" value="'+esc(parent?.category||'General')+'" placeholder="Raw material, packaging, finished good"></div><div class="field"><label>Default PO class</label><select name="assignmentCategory">'+choices+'</select></div><div class="field"><label>PO assignment reference</label><input name="assignmentRef" value="'+esc(parent?.assignmentRef||'WH-BKK')+'" required></div><div class="field"><label>GL account</label><input id="productGL" value="'+assignmentType(parent?.assignmentCategory||'INVENTORY').glAccount+' · '+esc(assignmentType(parent?.assignmentCategory||'INVENTORY').glName)+'" readonly></div><div class="field"><label>Unit</label><input name="uom" value="'+esc(parent?.uom||'pcs')+'" required></div><div class="field"><label>Unit cost ($)</label><input name="cost" type="number" min="0" step="any" value="'+(parent?.cost||0)+'" required></div><div class="field"><label>Selling price ($)</label><input name="price" type="number" min="0" step="any" value="'+(parent?.price||0)+'" required></div><div class="field"><label>Reorder point</label><input name="reorder" type="number" min="0" step="any" value="'+(parent?.reorder||0)+'" required></div><div class="field"><label>Opening on-hand quantity</label><input name="onHand" type="number" min="0" step="any" value="0" required></div><div class="form-note">A product can have any number of levels, or no child/parent hierarchy. The PO class determines the default GL account.</div></div></div><div class="modal-foot"><button class="btn" type="button" onclick="closeModal()">Cancel</button><button class="btn btn-primary" type="submit">Save product</button></div></form></div>';$('#modal-root').querySelector('[name="assignmentCategory"]').onchange=e=>{const a=assignmentType(e.target.value);$('#productGL').value=a.glAccount+' · '+a.glName}}
function productLevel(id){let n=1,p=product(id),seen=new Set();while(p?.parentId&&!seen.has(p.parentId)){seen.add(p.parentId);n++;p=product(p.parentId)}return n}
function openProductClassModal(id){const p=product(id),choices=ASSIGNMENT_TYPES.map(a=>'<option value="'+a.id+'" '+(a.id===p.assignmentCategory?'selected':'')+'>'+esc(a.label)+'</option>').join('');$('#modal-root').innerHTML='<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><form class="modal" onsubmit="saveProductClass(event,\''+p.id+'\')"><div class="modal-head"><div><h2>Edit material PO class</h2><p>'+esc(p.name)+' · new purchase orders inherit the saved class.</p></div><button type="button" class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Default PO class</label><select name="assignmentCategory" id="materialClassSelect">'+choices+'</select></div><div class="field"><label>Assignment reference</label><input name="assignmentRef" id="materialClassRef" value="'+esc(p.assignmentRef)+'" required></div><div class="field"><label>Mapped GL account</label><input id="materialClassGL" value="'+esc(p.glAccount)+' · '+esc(assignmentType(p.assignmentCategory).glName)+'" readonly></div><div class="form-note">This changes the material default only. Existing purchase orders keep their saved account assignment.</div></div></div><div class="modal-foot"><button class="btn" type="button" onclick="closeModal()">Cancel</button><button class="btn btn-primary" type="submit">Save PO class</button></div></form></div>';$('#materialClassSelect').onchange=e=>{const a=assignmentType(e.target.value);$('#materialClassRef').value=a.reference;$('#materialClassGL').value=a.glAccount+' · '+a.glName}}
function saveProductClass(e,id){e.preventDefault();const p=product(id),f=Object.fromEntries(new FormData(e.target)),a=assignmentType(f.assignmentCategory);p.materialClass=a.id;p.assignmentCategory=a.id;p.assignmentRef=f.assignmentRef.trim();p.glAccount=a.glAccount;save();closeModal();render();toast('PO class updated for '+p.name+'.')}
function saveProduct(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),a=assignmentType(f.assignmentCategory),parent=f.parentId||null;if(!f.name.trim()){toast('Enter a product name.');return}if(parent&&!product(parent)){toast('Select a valid parent product.');return}const p={id:newId('PRD',db.products,5),name:f.name.trim(),category:f.category.trim()||'General',parentId:parent,uom:f.uom.trim(),cost:Number(f.cost),price:Number(f.price),reorder:Number(f.reorder),onHand:Number(f.onHand),materialClass:a.id,assignmentCategory:a.id,assignmentRef:f.assignmentRef.trim(),glAccount:a.glAccount};db.products.push(p);save();closeModal();render();toast(p.name+' added at level '+productLevel(p.id)+'.')}
function materialPlanningPage(){const plans=db.products.map(p=>({p,...materialPlan(p)})),shortages=plans.filter(x=>x.required>0).length,open=db.purchases.filter(isInboundPurchase),overdue=open.filter(x=>logisticsState(x)==='Overdue').length,inboundCount=open.length;return heading('Material planning','Connect stock, open customer demand, inbound purchase orders, and supplier delivery dates','<button class="btn" onclick="go(\'inventory\')">View inventory</button><button class="btn btn-primary" onclick="go(\'purchasing\')">View purchase orders</button>')+'<div class="metrics">'+metric('Materials below reorder',shortages,'Net of open demand and inbound supply','⚑')+metric('Inbound purchase orders',inboundCount,'Open supplier orders','↙')+metric('Overdue inbound',overdue,'Needs logistics follow-up','◷')+metric('Open sales demand',db.sales.filter(x=>x.status==='Open').length,'Orders reserved against projected stock','↗')+'</div><div class="notice"><b>Planning rule:</b> Projected stock = on hand + open purchase order quantity − open sales order quantity. Suggested quantity raises projected stock to the reorder point. Receipt of a PO updates Inventory automatically. Inbound supply is counted before ETA, so review late or missing dates before relying on the projection.</div><div class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Material requirements</div><div class="panel-subtitle">Create a purchase order directly from a shortfall</div></div><button class="text-link" onclick="go(\'inventory\')">Inventory →</button></div><div class="table-wrap"><table class="planning-table"><thead><tr><th>Material</th><th>On hand</th><th>Open demand</th><th>Inbound</th><th>Projected stock</th><th>Reorder point</th><th>Suggested qty</th><th>Next ETA</th><th></th></tr></thead><tbody>'+plans.map(x=>'<tr><td><div class="td-strong">'+esc(x.p.name)+'</div><small>'+esc(x.p.id)+' · '+esc(x.p.category)+'</small></td><td>'+x.p.onHand+' '+esc(x.p.uom)+'</td><td>'+x.demand+' '+esc(x.p.uom)+'</td><td>'+x.inbound+' '+esc(x.p.uom)+(x.inboundOrders.length?' <small>('+x.inboundOrders.length+' PO)</small>':'')+'</td><td class="'+(x.projected<=x.p.reorder?'plan-low':'')+'">'+x.projected+' '+esc(x.p.uom)+'</td><td>'+x.p.reorder+' '+esc(x.p.uom)+'</td><td class="td-strong">'+(x.required?x.required+' '+esc(x.p.uom):'—')+'</td><td>'+(x.eta|| (x.inbound?'ETA missing':'—'))+'</td><td>'+(x.required?'<button class="btn btn-sm btn-primary" onclick="openModal(\'purchase\',\''+x.p.id+'\','+x.required+')">Create PO</button>':'<span class="status received">Covered</span>')+'</td></tr>').join('')+'</tbody></table></div></div><div class="panel table-panel inbound-panel"><div class="panel-head"><div><div class="panel-title">Inbound delivery schedule</div><div class="panel-subtitle">Supplier logistics feeding the material plan</div></div><button class="text-link" onclick="go(\'purchasing\')">All purchase orders →</button></div><div class="table-wrap"><table><thead><tr><th>PO</th><th>Supplier</th><th>Material</th><th>Qty</th><th>Expected</th><th>Carrier / reference</th><th>Logistics status</th><th></th></tr></thead><tbody>'+(open.slice().sort((a,b)=>(a.expectedDate||'9999').localeCompare(b.expectedDate||'9999')).map(po=>'<tr><td class="td-strong">'+po.id+'</td><td>'+esc(po.vendor)+'</td><td>'+esc(product(po.product)?.name||po.product)+'</td><td>'+po.qty+' '+esc(product(po.product)?.uom||'')+'</td><td>'+(po.expectedDate||'Not set')+'</td><td>'+esc([po.carrier,po.trackingRef].filter(Boolean).join(' · ')||'—')+'</td><td>'+status(logisticsState(po))+'</td><td><button class="btn btn-sm" onclick="openLogisticsModal(\''+po.id+'\')">Update</button></td></tr>').join('')||'<tr><td class="empty" colspan="8">No open inbound purchase orders.</td></tr>')+'</tbody></table></div></div>'}
function openLogisticsModal(id){const po=db.purchases.find(x=>x.id===id);if(!po)return;$('#modal-root').innerHTML='<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><form class="modal" onsubmit="saveLogistics(event,\''+po.id+'\')"><div class="modal-head"><div><h2>Update inbound delivery</h2><p>'+esc(po.id)+' · '+esc(po.vendor)+' · '+esc(product(po.product)?.name||po.product)+'</p></div><button type="button" class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Expected arrival</label><input type="date" name="expectedDate" value="'+(po.expectedDate||'')+'"></div><div class="field"><label>Carrier</label><input name="carrier" value="'+esc(po.carrier||'')+'" placeholder="Supplier or carrier"></div><div class="field full"><label>Tracking / delivery reference</label><input name="trackingRef" value="'+esc(po.trackingRef||'')+'" placeholder="Optional reference"></div></div></div><div class="modal-foot"><button class="btn" type="button" onclick="closeModal()">Cancel</button><button class="btn btn-primary" type="submit">Save delivery details</button></div></form></div>'}
function saveLogistics(e,id){e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),po=db.purchases.find(x=>x.id===id);if(!po)return;po.expectedDate=f.expectedDate;po.carrier=f.carrier.trim();po.trackingRef=f.trackingRef.trim();save();closeModal();render();toast('Inbound delivery details updated.')}function kpiDef(id){return KPI_DEFS.find(k=>k.id===id)}
function kpiValue(n,unit){return Number(n).toLocaleString('en-US',{maximumFractionDigits:2})+(unit==='%'?'%':' '+unit)}
function kpiMet(k,actual,target){return k.direction==='up'?actual>=target:actual<=target}
function kpiStatus(k,row){return !row?'<span class="status draft">Not entered</span>':kpiMet(k,row.actual,row.target)?'<span class="status received">On target</span>':'<span class="status low">Needs attention</span>'}
function supplyChainPage(){const periods=[...new Set([currentPeriod(),...db.kpis.map(x=>x.period)])].sort().reverse(),period=new URLSearchParams(location.hash.split('?')[1]||'').get('period')||periods[0],rows=KPI_DEFS.map(k=>({k,row:db.kpis.find(x=>x.kpi===k.id&&x.period===period)})),tracked=rows.filter(x=>x.row),met=tracked.filter(x=>kpiMet(x.k,x.row.actual,x.row.target)).length,att=tracked.length?Math.round(met/tracked.length*100)+'%':'—';return heading('Supply chain KPIs','Monthly numeric tracking for purchasing, suppliers, deliveries, inventory, team performance, and issue resolution','<button class="btn btn-primary" onclick="openModal(\'kpi\')">＋ Record measurement</button>')+'<div class="metrics">'+metric('KPIs tracked',tracked.length+' / '+KPI_DEFS.length,'Measurements entered this period','◉')+metric('Targets met',met,'Of the KPIs with a measurement','✓')+metric('Target attainment',att,'Share of tracked KPIs on target','↗')+metric('Measurement records',db.kpis.length,'Saved in this browser','▤')+'</div><div class="panel kpi-guide"><div class="panel-title">How to read the tracker</div><p>Enter one actual result and target for each KPI each month. Percentages use the formulas below. Cost control and cycle time are lower-is-better; the other measures are higher-is-better. Results are stored in this browser profile.</p></div><div class="page-tools kpi-tools"><label class="period-label">Reporting month <select class="search" id="kpiPeriod">'+periods.map(x=>'<option '+(x===period?'selected':'')+' value="'+x+'">'+new Date(x+'-02').toLocaleDateString('en-US',{month:'long',year:'numeric'})+'</option>').join('')+'</select></label><button class="btn" onclick="openModal(\'kpi\')">＋ Add measurement</button></div><div class="panel table-panel"><div class="table-wrap"><table class="kpi-table"><thead><tr><th>Performance measure</th><th>Actual</th><th>Target</th><th>Progress</th><th>Status</th><th>Action</th></tr></thead><tbody>'+rows.map(({k,row})=>'<tr><td><div class="kpi-name">'+k.icon+' '+k.name+'</div><div class="kpi-formula">'+k.formula+'</div></td><td class="td-strong">'+(row?kpiValue(row.actual,k.unit):'—')+'</td><td>'+(row?kpiValue(row.target,k.unit):'—')+'</td><td>'+(row?'<div class="kpi-progress"><span class="'+(kpiMet(k,row.actual,row.target)?'good':'warn')+'" style="width:'+Math.min(100,Math.max(3,k.direction==='up'?row.actual/Math.max(row.target,.001)*100:row.target/Math.max(row.actual,.001)*100))+'%"></span></div>':'—')+'</td><td>'+kpiStatus(k,row)+'</td><td><button class="btn btn-sm" onclick="openKpiModal(\''+(row?row.id:'')+'\',\''+k.id+'\',\''+period+'\')">'+(row?'Edit':'Enter')+'</button></td></tr>').join('')+'</tbody></table></div></div><div class="panel table-panel kpi-history"><div class="panel-head"><div><div class="panel-title">Measurement history</div><div class="panel-subtitle">Previous months and saved entries</div></div></div><div class="table-wrap"><table><thead><tr><th>Month</th><th>KPI</th><th>Actual</th><th>Target</th><th>Status</th><th>Note</th><th></th></tr></thead><tbody>'+(db.kpis.slice().sort((a,b)=>b.period.localeCompare(a.period)).map(r=>{const k=kpiDef(r.kpi);return '<tr><td>'+r.period+'</td><td>'+esc(k?k.name:r.kpi)+'</td><td>'+(k?kpiValue(r.actual,k.unit):r.actual)+'</td><td>'+(k?kpiValue(r.target,k.unit):r.target)+'</td><td>'+(k?kpiStatus(k,r):'')+'</td><td>'+esc(r.note||'—')+'</td><td><button class="text-link" onclick="deleteKpi(\''+r.id+'\')">Delete</button></td></tr>'}).join('')||'<tr><td class="empty" colspan="7">No measurements yet. Record your first monthly result above.</td></tr>')+'</tbody></table></div></div>'}
function openKpiModal(id='',selected='',period=''){const row=db.kpis.find(x=>x.id===id),k=row?kpiDef(row.kpi):(kpiDef(selected)||KPI_DEFS[0]),month=period||currentPeriod(),choices=KPI_DEFS.map(x=>'<option value="'+x.id+'" '+(x.id===(row?row.kpi:k.id)?'selected':'')+'>'+x.name+'</option>').join('');$('#modal-root').innerHTML='<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><form class="modal" onsubmit="saveKpi(event,\''+(row?row.id:'')+'\')"><div class="modal-head"><div><h2>'+(row?'Edit KPI measurement':'Record KPI measurement')+'</h2><p>Enter a numeric actual and target for the reporting month.</p></div><button type="button" class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid"><div class="field full"><label>Performance measure</label><select name="kpi" id="kpiSelect">'+choices+'</select></div><div class="form-note full" id="kpiFormula"></div><div class="field"><label>Reporting month</label><input name="period" type="month" value="'+(row?row.period:month)+'" required></div><div class="field"><label>Actual result</label><input name="actual" type="number" min="0" step="any" value="'+(row?row.actual:'')+'" placeholder="e.g. 95" required></div><div class="field"><label>Target</label><input name="target" type="number" min="0" step="any" value="'+(row?row.target:'')+'" placeholder="e.g. 98" required></div><div class="field full"><label>Notes / source</label><input name="note" value="'+esc(row?row.note||'':'')+'" placeholder="Optional: source report or context"></div></div></div><div class="modal-foot"><button class="btn" type="button" onclick="closeModal()">Cancel</button><button class="btn btn-primary" type="submit">Save measurement</button></div></form></div>';const update=()=>{const def=kpiDef($('#kpiSelect').value);$('#kpiFormula').textContent=def.formula+' · Unit: '+def.unit+' · '+(def.direction==='up'?'Higher is better':'Lower is better')};$('#kpiSelect').onchange=update;update()}
function saveKpi(e,id){e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),actual=Number(f.actual),target=Number(f.target),k=kpiDef(f.kpi);if(!k||!f.period||!Number.isFinite(actual)||!Number.isFinite(target)||actual<0||target<0||(k.unit==='%'&&(actual>100||target>100))){toast('Enter a valid month, actual, and target.');return}if(db.kpis.some(x=>x.kpi===k.id&&x.period===f.period&&x.id!==id)){toast('A measurement for this KPI and month already exists. Edit that record instead.');return}const row={id:id||'KPI-'+Date.now(),kpi:k.id,period:f.period,actual,target,note:f.note.trim()};if(id)db.kpis[db.kpis.findIndex(x=>x.id===id)]=row;else db.kpis.unshift(row);save();closeModal();location.hash='supplychain?period='+f.period;go('supplychain');toast('KPI measurement saved.')}
function deleteKpi(id){if(!confirm('Delete this KPI measurement?'))return;db.kpis=db.kpis.filter(x=>x.id!==id);save();render();toast('Measurement deleted.')}function inventoryPage(){return heading('Inventory','Materials management · Track stock, value, and reorder levels','<button class="btn btn-primary" onclick="openModal(\'adjust\')">＋ Stock adjustment</button>')+'<div class="metrics">'+metric('Stock keeping units',db.products.length,'Materials and finished goods','▦')+metric('Total stock value',money(invValue()),'Standard cost basis','◈')+metric('Below reorder point',db.products.filter(p=>p.onHand<=p.reorder).length,'Review replenishment','⚑')+metric('Open purchase orders',db.purchases.filter(p=>p.status==='Open').length,'Expected receipts','↙')+'</div><div class="page-tools"><input class="search" id="tableSearch" placeholder="⌕  Search products..."></div><div class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>SKU</th><th>Product</th><th>Category</th><th>On hand</th><th>Reorder point</th><th>Unit cost</th><th>Stock value</th><th>Availability</th></tr></thead><tbody>'+db.products.map(p=>'<tr><td class="td-strong">'+p.id+'</td><td>'+esc(p.name)+'</td><td>'+p.category+'</td><td>'+p.onHand+' '+p.uom+'</td><td>'+p.reorder+' '+p.uom+'</td><td>'+money(p.cost)+'</td><td>'+money(p.onHand*p.cost)+'</td><td>'+status(p.onHand<=p.reorder?'Low':'In stock')+'</td></tr>').join('')+'</tbody></table></div></div>'}
function financePage(){const dr=db.ledger.reduce((a,x)=>a+x.debit,0),cr=db.ledger.reduce((a,x)=>a+x.credit,0);return heading('Finance','Record to report · Operational postings and general ledger','<button class="btn" onclick="resetData()">↻ Reset demo data</button>')+'<div class="notice">Trial accounting posts balanced double-entry journals when orders are invoiced and purchase receipts are posted. Tax configuration, manual journals, and period close belong in the next implementation phase.</div><div class="metrics">'+metric('Accounts receivable',money(db.ledger.filter(x=>x.account==='Accounts receivable').reduce((a,x)=>a+x.debit-x.credit,0)),'Posted customer invoices','↗')+metric('Accounts payable',money(db.ledger.filter(x=>x.account==='Accounts payable').reduce((a,x)=>a+x.credit-x.debit,0)),'Posted supplier receipts','↙')+metric('Debits posted',money(dr),'All journal entries','◈')+metric('Trial balance difference',money(Math.abs(dr-cr)),dr===cr?'Books are balanced':'Investigate balances','✓')+'</div><div class="panel table-panel"><div class="panel-head"><div><div class="panel-title">General ledger journal</div><div class="panel-subtitle">Automatically generated operational postings</div></div>'+status(dr===cr?'Balanced':'Low')+'</div><div class="table-wrap"><table><thead><tr><th>Journal</th><th>Date</th><th>Reference</th><th>Account</th><th>Description</th><th>Debit</th><th>Credit</th></tr></thead><tbody>'+db.ledger.map(x=>'<tr><td class="td-strong">'+x.id+'</td><td>'+x.date+'</td><td>'+x.reference+'</td><td>'+x.account+'</td><td>'+x.memo+'</td><td>'+(x.debit?money(x.debit):'—')+'</td><td>'+(x.credit?money(x.credit):'—')+'</td></tr>').join('')+'</tbody></table></div></div>'}
function mastersPage(){return heading('Master data','Shared records used by every business process','')+'<div class="section-grid">'+[['▦','Products & materials',db.products.length,'Stock, units of measure, standard cost, selling price, and reorder policy.'],['♙','Customers',db.customers.length,'Customer accounts for sales orders and accounts receivable.'],['♧','Suppliers',db.vendors.length,'Vendor accounts for purchase orders and accounts payable.'],['◈','Chart of accounts',6,'Trial accounts for cash, inventory, receivables, payables, revenue, and cost of goods sold.']].map(x=>'<div class="module-card"><span class="metric-icon">'+x[0]+'</span><h3>'+x[1]+'</h3><p>'+x[3]+'</p><div class="module-card-footer"><span>'+x[2]+' records</span><span>Master data</span></div></div>').join('')+'</div><div class="panel" style="margin-top:15px"><div class="panel-title">Connected ERP process</div><div class="flow"><div class="flow-step done"><span>1</span>Product and price</div><div class="flow-line"></div><div class="flow-step done"><span>2</span>Sales or purchase document</div><div class="flow-line"></div><div class="flow-step done"><span>3</span>Stock movement</div><div class="flow-line"></div><div class="flow-step done"><span>4</span>Financial posting</div></div></div>'}
function roadmapPage(){const phases=[['PHASE 0 · NOW','Local trial','Validate process language and end-to-end scenarios with the team.',['Sales order → ship → invoice → receivable and revenue journal','Purchase order → goods receipt → inventory and payable journal','Stock inquiry, reorder flags, and browser-local persistence']],['PHASE 1','Discovery & blueprint','Agree the operating model before production development.',['Map order-to-cash, procure-to-pay, inventory, accounting, and close','Confirm Thai VAT, withholding tax, currencies, and document rules with an accountant','Define roles, approvals, data ownership, reporting, and migration scope']],['PHASE 2','ERP foundation','Replace browser-local state with a secure multi-user system.',['PostgreSQL schema, migrations, API, authentication, authorization, and tenant boundaries','Numbering, validation, audit history, backups, and deployment environments','Product, customer, supplier, warehouse, unit, price, and account masters']],['PHASE 3','Core operations','Build transaction lifecycles, reversals, and exception handling.',['Sales order, delivery, invoice, credit note, and collections','Purchase request/order, receipt, supplier invoice, and payment','Multi-warehouse stock ledger, reservations, transfers, counts, and valuation']],['PHASE 4','Finance & controls','Make accounting the source of truth with traceable journals.',['Configured chart of accounts, subledgers, VAT, tax invoices, and bank reconciliation','Posting periods, approvals, close checklist, statements, and audit reports','Segregation of duties and immutable event history']],['PHASE 5','Pilot & rollout','Prove workflows with real users and controlled data.',['Migrate and reconcile masters, open orders, and opening balances','User acceptance, training, security review, restore test, and cutover rehearsal','Pilot one entity/location, resolve issues, then roll out in waves']]];return heading('Implementation plan','A staged path from trial to a dependable small-business ERP','')+'<div class="notice"><b>Scope:</b> A full SAP-level ERP is a program of work, not a single code drop. This trial demonstrates connected processes; it is not production accounting or compliant Thai tax software.</div><div class="roadmap">'+phases.map((p,i)=>'<div class="panel roadmap-phase"><div class="phase-tag">'+p[0]+(i===0?' · COMPLETE':'')+'</div><div><h3>'+p[1]+'</h3><p>'+p[2]+'</p><ul>'+p[3].map(x=>'<li>'+x+'</li>').join('')+'</ul></div></div>').join('')+'</div>'}
function wireSearch(){const i=$('#tableSearch');if(i)i.oninput=()=>$('#page').querySelectorAll('tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(i.value.toLowerCase())?'':'none');const p=$('#kpiPeriod');if(p)p.onchange=()=>{location.hash='supplychain?period='+p.value;render()}}function openModal(type,prefillProduct='',prefillQty=''){if(type==='kpi'){openKpiModal();return}if(type==='budget'){openBudgetModal();return}const isSales=type==='sales',isPurchase=type==='purchase',title=isSales?'Create sales order':isPurchase?'Create purchase order':'Adjust stock quantity',people=isSales?db.customers:db.vendors,pLabel=isSales?'Customer':'Supplier',productOpts=db.products.map(p=>'<option value="'+p.id+'" '+(p.id===prefillProduct?'selected':'')+'>'+esc(p.name)+' · '+money(isSales?p.price:p.cost)+'/'+p.uom+'</option>').join(''),eta=defaultEta();$('#modal-root').innerHTML='<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><form class="modal" onsubmit="submitModal(event,\''+type+'\')"><div class="modal-head"><div><h2>'+title+'</h2><p>'+((isSales||isPurchase)?'Start a connected ERP transaction.':'Positive adds stock; negative removes stock.')+'</p></div><button type="button" class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid">'+(isSales||isPurchase?'<div class="field"><label>'+pLabel+'</label><select name="party">'+people.map(x=>'<option>'+esc(x)+'</option>').join('')+'</select></div>':'')+'<div class="field"><label>Product</label><select name="product" id="f-product">'+productOpts+'</select></div><div class="field"><label>Quantity</label><input name="qty" type="number" min="0.01" step="any" value="'+(prefillQty||1)+'" required></div><div class="field"><label>'+(isSales?'Unit selling price ($)':isPurchase?'Unit cost ($)':'Quantity change (+ / −)')+'</label><input name="price" id="f-price" type="number" step="any" value="0" required></div>'+(isPurchase?'<div class="field"><label>Account assignment</label><select name="assignmentCategory" id="f-assignment">'+ASSIGNMENT_TYPES.map(a=>'<option value="'+a.id+'" '+(a.id==='INVENTORY'?'selected':'')+'>'+esc(a.label)+'</option>').join('')+'</select></div><div class="field"><label>Assignment reference</label><input name="assignmentRef" id="f-assignmentRef" value="WH-BKK" required></div><div class="field"><label>GL account</label><input id="f-assignmentGL" value="1100 · Inventory Asset" readonly></div><div class="field"><label>Expected arrival</label><input name="expectedDate" type="date" value="'+eta+'" required></div><div class="field"><label>Carrier</label><input name="carrier" placeholder="Supplier or carrier"></div><div class="field full"><label>Tracking / delivery reference</label><input name="trackingRef" placeholder="Optional reference"></div>':'')+(type==='adjust'?'<div class="field full"><label>Reason</label><input name="reason" value="Cycle count" required></div>':'')+'<div class="form-note">'+(isSales?'Shipping checks available stock, then posts the invoice and balanced journals.':isPurchase?'Select the account assignment and GL. Issuing the PO checks the approved budget for its period and reference.':'Trial stock adjustment is saved for review.')+'</div></div></div><div class="modal-foot"><button class="btn" type="button" onclick="closeModal()">Cancel</button><button class="btn btn-primary" type="submit">'+(isSales?'Create order':isPurchase?'Save as draft PO':'Post adjustment')+'</button></div></form></div>';const update=()=>{const p=product($('#f-product').value);$('#f-price').value=isSales?p.price:isPurchase?p.cost:0;if(isPurchase){const a=assignmentType(p.assignmentCategory);$('#f-assignment').value=a.id;$('#f-assignmentRef').value=p.assignmentRef||a.reference;$('#f-assignmentGL').value=(p.glAccount||a.glAccount)+' · '+a.glName}};$('#f-product').onchange=update;update();if(isPurchase)$('#f-assignment').onchange=()=>{const a=assignmentType($('#f-assignment').value);$('#f-assignmentRef').value=a.reference;$('#f-assignmentGL').value=a.glAccount+' · '+a.glName}}function closeModal(){$('#modal-root').innerHTML=''}function submitModal(e,type){e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),p=product(f.product),qty=Number(f.qty),price=Number(f.price);if(type==='sales'){db.sales.unshift({id:newId('SO',db.sales,1048),customer:f.party,product:p.id,qty,unitPrice:price,status:'Open',date:dateNow()});toast('Sales order created. Ready to fulfill.')}else if(type==='purchase'){const assignment=assignmentType(f.assignmentCategory);db.purchases.unshift({id:newId('PO',db.purchases,2031),vendor:f.party,product:p.id,qty,unitCost:price,status:'Draft',date:dateNow(),expectedDate:f.expectedDate,carrier:(f.carrier||'').trim(),trackingRef:(f.trackingRef||'').trim(),assignmentCategory:assignment.id,assignmentRef:f.assignmentRef.trim(),glAccount:assignment.glAccount});toast('Draft purchase order saved. Check and issue it to commit budget and add inbound supply.')}else{const delta=price;if(!delta){toast('Enter a non-zero quantity change.');return}if(p.onHand+delta<0){toast('Adjustment would make stock negative.');return}p.onHand+=delta;db.adjustments.unshift({id:newId('ADJ',db.adjustments,0),product:p.id,delta,reason:f.reason,date:dateNow()});toast('Stock adjustment posted.')}save();closeModal();render()}function addJournal(ref,account,debit,credit,memo){db.ledger.unshift({id:newId('JE',db.ledger,3108),date:dateNow(),reference:ref,account,debit,credit,memo})}function shipSale(id){const s=db.sales.find(x=>x.id===id),p=product(s.product);if(p.onHand<s.qty){toast('Not enough stock. '+p.onHand+' '+p.uom+' available.');return}p.onHand-=s.qty;s.status='Invoiced';const amount=s.qty*s.unitPrice,cost=s.qty*p.cost;addJournal(id,'Accounts receivable',amount,0,'Customer invoice');addJournal(id,'Sales revenue',0,amount,'Product sale');addJournal(id,'Cost of goods sold',cost,0,'Cost of sale');addJournal(id,'Inventory',0,cost,'Inventory relief');save();render();toast(id+' shipped and invoiced; stock and finance updated.')}function receivePO(id){const po=db.purchases.find(x=>x.id===id);if(!isInboundPurchase(po))return;po.status='Received';const p=product(po.product),amt=po.qty*po.unitCost,assignment=assignmentType(po.assignmentCategory);if(po.assignmentCategory==='INVENTORY')p.onHand+=po.qty;addJournal(id,assignment.glName,amt,0,'Goods received · '+po.assignmentRef);addJournal(id,'Accounts payable',0,amt,'Supplier liability');save();render();toast(id+' received; stock and finance updated.')}function resetData(){if(!confirm('Reset all trial data to original demo records? This clears saved transactions in this browser.'))return;db=structuredClone(seed);db.kpis=[];db.budgets=structuredClone(BUDGET_SEED);db.purchases.forEach(p=>{p.assignmentCategory='INVENTORY';p.assignmentRef='WH-BKK';p.glAccount='1100'});save();go('overview');toast('Demo data restored.')}
let toastTimer;function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}nav();render();
